547	    pv_box64<T, 0, HDV/2, CN>(acc_o, P, make_smem_desc(sV_base, LBO, SW_V_SBO, 1));
548	    if constexpr (HDV >= 128) pv_box64<T, 32, HDV/2, CN>(acc_o, P, make_smem_desc(sV_base + 1*BOX, LBO, SW_V_SBO, 1));
549	    if constexpr (HDV >= 192) pv_box64<T, 64, HDV/2, CN>(acc_o, P, make_smem_desc(sV_base + 2*BOX, LBO, SW_V_SBO, 1));
550	    if constexpr (HDV >= 256) pv_box64<T, 96, HDV/2, CN>(acc_o, P, make_smem_desc(sV_base + 3*BOX, LBO, SW_V_SBO, 1));
551	}
552	// First K-block: QK only (s = Q.K^T), HD-generic.
553	template <typename T, int HDt, int CN, int CM = CTA_M>
554	__device__ __forceinline__ void qk_gemm_g(float (&s)[CN/2], uint32_t sQ_wg, uint32_t sK_base) {
555	    uint64_t baseA = make_smem_desc(sQ_wg,   SW_QK_LBO, SW_QK_SBO, 1);
556	    uint64_t baseB = make_smem_desc(sK_base, SW_QK_LBO, SW_QK_SBO, 1);
557	    qk_batch_g<T, HDt, CN, CM>(s, baseA, baseB, 0);
558	    asm volatile("wgmma.wait_group.sync.aligned 0;\n" ::: "memory");
559	    wg_fence_c(s);
560	}
561	// Fused QK (next block) + rescale O + PV (current block), HD/HDV/CN-generic. acc_o has HDV/2 regs.
562	template <typename T, int HD, int HDV, int CN, int CM = CTA_M>
563	__device__ __forceinline__ void qk_rs_pv_g(float (&s)[CN/2], float (&acc_o)[HDV/2], const uint32_t (&P)[CN/4],
564	                                           uint32_t sQ_wg, uint32_t sK_base, uint32_t sV_base, const float* sc) {
565	    uint64_t baseA = make_smem_desc(sQ_wg,   SW_QK_LBO, SW_QK_SBO, 1);
566	    uint64_t baseB = make_smem_desc(sK_base, SW_QK_LBO, SW_QK_SBO, 1);
567	    qk_batch_g<T, HD, CN, CM>(s, baseA, baseB, 0);
568	    rescale_o_g(acc_o, sc);
569	    pv_boxes<T, HDV, CN>(acc_o, P, sV_base);
570	}
571	// Final PV (last block, after the loop), HDV/CN-generic.
572	template <typename T, int HDV, int CN>
573	__device__ __forceinline__ void pv_final_g(float (&acc_o)[HDV/2], const uint32_t (&P)[CN/4], uint32_t sV_base) {
574	    pv_boxes<T, HDV, CN>(acc_o, P, sV_base);
575	    asm volatile("wgmma.wait_group.sync.aligned 0;\n" ::: "memory");
576	    wg_fence_c(acc_o);
577	    wg_fence_a(P);
578	}
